{"command":"cat > /tmp/stackalloc_nint.cs << 'EOF'
using System;

class Program
{
    static void Main()
    {
        Span<nint> span = stackalloc nint[4];
        span[0] = 10;
        span[1] = 20;
        span[2] = 30;
        span[3] = 40;

        Console.WriteLine($"Length: {span.Length}");
        for (int i = 0; i < span.Length; i++)
            Console.WriteLine($"  span[{i}] = {span[i]}");

        Span<nuint> uspan = stackalloc nuint[3];
        uspan[0] = 100;
        uspan[1] = 200;
        uspan[2] = 300;

        Console.WriteLine($"Unsigned length: {uspan.Length}");
        for (int i = 0; i < uspan.Length; i++)
            Console.WriteLine($"  uspan[{i}] = {uspan[i]}");

        Console.WriteLine($"nint size: {sizeof(nint)} bytes");
    }
}
EOF
